import React, { useCallback, useEffect, useRef, useState, type ReactElement, type ReactNode } from 'react';
import { FlatList, StyleSheet, View, type LayoutChangeEvent, type StyleProp, type ViewStyle } from 'react-native';

import {
  DARK_FILE_VIEW_COLORS,
  FileExpandedRow,
  FileGridCell,
  FileListRow,
  type FileViewColors,
  type RenderFileThumb,
} from './FileRows';
import {
  fileSourceKey,
  gridMetrics,
  type FileReader,
  type FileSource,
  type FileViewItem,
  type FileViewMode,
} from './fileViewLogic';

/**
 * A list of files shown as a list, an expanded list or a grid. The same files, the same
 * touches, three layouts. This is the piece an app uses when it has no list of its own; an app
 * that does (it has pull-to-refresh, swipe-to-delete, its own header) uses the three row
 * shapes from `FileRows` inside it instead.
 *
 * Everything past `items` and `mode` is optional and changes nothing when left out. That is the
 * rule for anything added later: a new ability is a new optional prop, off by default, so an
 * app that does not ask for it looks and behaves exactly as it did.
 */

export type FileViewsProps<Extra = unknown> = {
  items: readonly FileViewItem<Extra>[];
  mode: FileViewMode;
  /** A touch on a file. */
  onOpen?: (item: FileViewItem<Extra>) => void;
  /** A long press on a file (and the more button of the expanded view): the app's menu for it. */
  onMore?: (item: FileViewItem<Extra>) => void;
  colors?: FileViewColors;
  /** Pictures across in the grid. Five unless the app says otherwise. */
  columns?: number;
  /** The app's own picture for a file; return null to get the standard one. */
  renderThumb?: RenderFileThumb<Extra>;
  /** The app's own row for the expanded view, when it already has one. */
  renderExpanded?: (item: FileViewItem<Extra>, index: number) => ReactElement | null;
  /** Shown above the files, and scrolls with them. */
  header?: ReactNode;
  /** Shown when there are no files. */
  empty?: ReactNode;
  /** Room left under the last file, for a toolbar that floats over the list. */
  bottomRoom?: number;
  style?: StyleProp<ViewStyle>;
};

export function FileViews<Extra = unknown>({
  items,
  mode,
  onOpen,
  onMore,
  colors = DARK_FILE_VIEW_COLORS,
  columns = 5,
  renderThumb,
  renderExpanded,
  header,
  empty,
  bottomRoom = 0,
  style,
}: FileViewsProps<Extra>) {
  const [width, setWidth] = useState(0);
  const onLayout = useCallback((event: LayoutChangeEvent) => setWidth(event.nativeEvent.layout.width), []);
  const grid = gridMetrics(width, { columns });
  const isGrid = mode === 'grid';

  return (
    <View style={[styles.fill, style]} onLayout={onLayout}>
      {width > 0 ? (
        <FlatList
          // A list cannot change its number of columns while it is on screen, so each view is a list of its own.
          key={isGrid ? `grid-${grid.columns}` : mode}
          data={items}
          keyExtractor={(item) => item.id}
          numColumns={isGrid ? grid.columns : 1}
          columnWrapperStyle={isGrid ? { gap: grid.gap, paddingHorizontal: grid.edge } : undefined}
          contentContainerStyle={[
            isGrid ? { gap: grid.gap + 4, paddingTop: grid.edge } : null,
            { paddingBottom: bottomRoom },
            items.length === 0 ? styles.emptyContent : null,
          ]}
          ListHeaderComponent={header ? <>{header}</> : undefined}
          ListEmptyComponent={empty ? <>{empty}</> : undefined}
          showsVerticalScrollIndicator={false}
          renderItem={({ item, index }) => {
            const open = onOpen ? () => onOpen(item) : undefined;
            const more = onMore ? () => onMore(item) : undefined;
            if (isGrid) {
              return (
                <FileGridCell
                  item={item}
                  tile={grid.tile}
                  colors={colors}
                  onPress={open}
                  onLongPress={more}
                  renderThumb={renderThumb}
                />
              );
            }
            if (mode === 'list') {
              return (
                <FileListRow
                  item={item}
                  index={index}
                  colors={colors}
                  onPress={open}
                  onLongPress={more}
                  renderThumb={renderThumb}
                />
              );
            }
            return (
              renderExpanded?.(item, index) ?? (
                <FileExpandedRow
                  item={item}
                  divider={index !== 0}
                  colors={colors}
                  onPress={open}
                  onLongPress={more}
                  onMore={more}
                  renderThumb={renderThumb}
                />
              )
            );
          }}
        />
      ) : null}
    </View>
  );
}

// ---------------------------------------------------------------------------------------------
// Files from a place
// ---------------------------------------------------------------------------------------------

export type FileItemsState<Extra = unknown> = {
  items: FileViewItem<Extra>[];
  /** True until the first answer for this place. */
  loading: boolean;
  /** Why the place could not be listed, in the reader's own words. */
  error: string | null;
  reload: () => void;
};

/**
 * The files of a place (a folder on this device, or a key on the network), kept up to date.
 * The app writes the reader once; this asks it, asks again when the place says it changed, and
 * drops an answer that arrives after the place was swapped for another.
 */
export function useFileItems<Extra = unknown>(
  reader: FileReader<Extra>,
  source: FileSource | null,
): FileItemsState<Extra> {
  const [state, setState] = useState<Omit<FileItemsState<Extra>, 'reload'>>({ items: [], loading: !!source, error: null });
  const [round, setRound] = useState(0);
  const key = source ? fileSourceKey(source) : '';
  const latest = useRef({ reader, source });
  latest.current = { reader, source };

  useEffect(() => {
    const { reader: read, source: place } = latest.current;
    if (!place) {
      setState({ items: [], loading: false, error: null });
      return;
    }
    let current = true;
    const ask = () => {
      read
        .list(place)
        .then((items) => {
          if (current) setState({ items, loading: false, error: null });
        })
        .catch((problem: unknown) => {
          if (current) {
            setState((before) => ({
              items: before.items,
              loading: false,
              error: problem instanceof Error ? problem.message : String(problem),
            }));
          }
        });
    };
    setState((before) => ({ ...before, loading: true }));
    ask();
    const stop = read.watch?.(place, ask);
    return () => {
      current = false;
      stop?.();
    };
  }, [key, round]);

  const reload = useCallback(() => setRound((n) => n + 1), []);
  return { ...state, reload };
}

const styles = StyleSheet.create({
  fill: { flex: 1 },
  emptyContent: { flexGrow: 1, justifyContent: 'center' },
});
